insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('land-documents','land-documents',false,15728640,array['application/pdf','image/jpeg','image/png','image/webp','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create table if not exists public.parcel_documents(id uuid primary key default gen_random_uuid(),parcel_id uuid not null references public.land_parcels(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,document_type text not null check(document_type in('Ownership Deed','Registry','Mutation Record','Khasra / Khatauni','Survey Map','Compensation Award','Acquisition Notice','Identity Proof','Court Order','Other')),title text not null check(char_length(title) between 2 and 160),file_name text not null,storage_path text not null unique,mime_type text not null,file_size bigint not null check(file_size>0 and file_size<=15728640),verification_status text not null default 'Pending' check(verification_status in('Pending','Verified','Rejected')),review_notes text,uploaded_by uuid references auth.users(id) on delete set null,verified_by uuid references auth.users(id) on delete set null,verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint parcel_documents_verification_consistency check((verification_status='Verified' and verified_by is not null and verified_at is not null) or verification_status<>'Verified'));
create index if not exists parcel_documents_parcel_created_idx on public.parcel_documents(parcel_id,created_at desc);
create index if not exists parcel_documents_project_status_idx on public.parcel_documents(project_id,verification_status,created_at desc);
alter table public.parcel_documents enable row level security;revoke all on public.parcel_documents from anon;grant select,insert,update,delete on public.parcel_documents to authenticated;
create policy "Read parcel documents for accessible projects" on public.parcel_documents for select to authenticated using(private.can_access_project(project_id));
create policy "Authorized teams upload parcel documents" on public.parcel_documents for insert to authenticated with check(uploaded_by=(select auth.uid()) and private.can_access_project(project_id) and exists(select 1 from public.land_parcels lp where lp.id=parcel_id and lp.project_id=project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager']));
create policy "Authorized teams review parcel documents" on public.parcel_documents for update to authenticated using(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager'])) with check(private.can_access_project(project_id) and exists(select 1 from public.land_parcels lp where lp.id=parcel_id and lp.project_id=project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager']));
create policy "Admins and project managers delete parcel documents" on public.parcel_documents for delete to authenticated using(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager']));
create policy "Read files for accessible parcel projects" on storage.objects for select to authenticated using(bucket_id='land-documents' and exists(select 1 from public.land_parcels lp where lp.id=((storage.foldername(name))[2])::uuid and lp.project_id=((storage.foldername(name))[1])::uuid and private.can_access_project(lp.project_id)));
create policy "Authorized teams upload files to accessible parcels" on storage.objects for insert to authenticated with check(bucket_id='land-documents' and (storage.foldername(name))[1] is not null and (storage.foldername(name))[2] is not null and exists(select 1 from public.land_parcels lp where lp.id=((storage.foldername(name))[2])::uuid and lp.project_id=((storage.foldername(name))[1])::uuid and private.can_access_project(lp.project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager'])));
create policy "Authorized teams delete files from accessible parcels" on storage.objects for delete to authenticated using(bucket_id='land-documents' and exists(select 1 from public.land_parcels lp where lp.id=((storage.foldername(name))[2])::uuid and lp.project_id=((storage.foldername(name))[1])::uuid and private.can_access_project(lp.project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager'])));
